const movie = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Movie has required fields", function () {
    pm.expect(movie).to.have.property("_id");
    pm.expect(movie).to.have.property("title");
    pm.expect(movie).to.have.property("year");
});

pm.test("Movie fields have correct types", function () {
    pm.expect(movie.title).to.be.a("string");
    pm.expect(movie.year).to.be.a("number");
    pm.expect(movie.genres).to.be.an("array");
});

const data = pm.response.json();

pm.test("IMDB is a nested object", function () {
    pm.expect(data.imdb).to.be.an("object");
});

pm.test("Genres is an array", function () {
    pm.expect(data.genres).to.be.an("array");
});

pm.test("Movie title is a string", function () {
    pm.expect(data.title).to.be.a("string");
});

pm.test("Movie year is a number", function () {
    pm.expect(data.year).to.be.a("number");
});

pm.test("Release date has valid format", function () {
    if (data.released) {
        pm.expect(new Date(data.released).getTime()).not.to.be.NaN;
    }
});

const response = pm.response.json();

pm.test("POST status is successful", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

pm.test("Response is valid JSON", function () {
    pm.response.to.be.json;
});

pm.test("Movie was created with an ID", function () {
    pm.expect(response._id || response.insertedId).to.exist;
});

