const movie = pm.response.json();

pm.test("PUT status is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Movie title updated", function () {
    pm.expect(movie.title).to.eql("The Secret of Synevyr - Updated");
});

pm.test("Year and runtime updated", function () {
    pm.expect(movie.year).to.eql(2024);
    pm.expect(movie.runtime).to.eql(120);
});

const response = pm.response.json();

pm.test("DELETE status is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Movie deleted successfully", function () {
    pm.expect(response.message).to.eql("Документ видалено");
});

pm.test("Deleted movie ID matches request", function () {
    const movieId = pm.request.url.path.slice(-1)[0];
    pm.expect(response.deletedDocument._id).to.eql(movieId);
});
